/**
 * Connection lifecycle, flattened for the FFI.
 */

public enum ConnectionState: Equatable, Hashable {
    
    case idle
    case connecting
    case online
    case reconnecting(attempt: UInt32, retryInMs: UInt64
    )
    case failed(message: String, recoverable: Bool
    )





}

#if compiler(>=6)
extension ConnectionState: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeConnectionState: FfiConverterRustBuffer {
    typealias SwiftType = ConnectionState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ConnectionState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .idle
        
        case 2: return .connecting
        
        case 3: return .online
        
        case 4: return .reconnecting(attempt: try FfiConverterUInt32.read(from: &buf), retryInMs: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 5: return .failed(message: try FfiConverterString.read(from: &buf), recoverable: try FfiConverterBool.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ConnectionState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .idle:
            writeInt(&buf, Int32(1))
        
        
        case .connecting:
            writeInt(&buf, Int32(2))
        
        
        case .online:
            writeInt(&buf, Int32(3))
        
        
        case let .reconnecting(attempt,retryInMs):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(attempt, into: &buf)
            FfiConverterUInt64.write(retryInMs, into: &buf)
            
        
        case let .failed(message,recoverable):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(recoverable, into: &buf)
            
        }
    }
}


