/**
 * Anything the UI can be told about a failure.
 */
public 
enum SgError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case UnknownTarget(id: String
    )
    case Connection(message: String, recoverable: Bool
    )
    case Internal(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension SgError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSgError: FfiConverterRustBuffer {
    typealias SwiftType = SgError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SgError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .UnknownTarget(
            id: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Connection(
            message: try FfiConverterString.read(from: &buf), 
            recoverable: try FfiConverterBool.read(from: &buf)
            )
        case 3: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SgError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .UnknownTarget(id):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .Connection(message,recoverable):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(recoverable, into: &buf)
            
        
        case let .Internal(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


